update_rule.pseudocode:
mandate_active = (t >= mandate_start_day) and (t <= mandate_end_day)
issued_fines = 0
for each location L:
  effective_enforcement = enforcement_level * location_policy_effectiveness_multiplier
  for each person p in L.current_occupants:
    if mandate_active and p.mask_wearing_today == 0:
      if bernoulli(effective_enforcement):
        if not bernoulli(enforcement_false_positive_rate):
          p.last_fined_day = t
          p.penalty_memory += fine_amount
          issued_fines += 1
for each person p:
  # decay penalty memory
  decay = exp(-ln(2) / penalty_memory_half_life_days)
  p.penalty_memory *= decay
emit metrics.fines_issued_daily = issued_fines
